const MORE = {"whatsapp-booking":{"sub":"بيرد على عملاءك على واتساب، يحجزلهم المواعيد، ويبعت التذكير لوحده","problem":"الرسايل بيترد عليها متأخر، فالعميل بيروح يحجز عند غيرك. وفيه عملاء بيحجزوا وما بييجوش.","steps":["العميل يبعت رسالة على واتساب في أي وقت، حتى لو بالليل","المساعد يرد عليه ويجاوب أسئلته من معلومات شغلك إنت","يعرض عليه المواعيد الفاضية من التقويم ويحجزله","يبعتله تذكير قبل الميعاد بيوم وبساعة، ولو عايز يغيّر الميعاد يغيّرهوله"],"plain":["تخيّل موظف استقبال قاعد على واتساب 24 ساعة، ما بينامش وما بياخدش إجازة. أي عميل يبعت رسالة، بيرد عليه في ثواني: يقوله الأسعار ومواعيد الشغل من المعلومات اللي إنت مديهاله، وبعدين يحجزله الميعاد بنفسه.","إنت مش محتاج تمسك الموبايل طول اليوم. تصحى الصبح تلاقي الحجوزات متسجلة في التقويم، والعميل وصله التذكير. ولو حد سأل سؤال صعب المساعد مش عارف إجابته، بيحوّل المحادثة لموظف من عندك."],"story":"عيادة بتقفل بالليل، والساعة 11:52 واحدة تبعت: «عايزة أحجز ميعاد بكرة». المساعد يرد في ثواني ويعرض عليها ميعادين فاضيين، هي تختار 6:30، والحجز يتسجل. من غير المساعد، الرسالة دي كانت هتستنى للصبح، وممكن تكون حجزت عند حد تاني.","gains":[["ما فيش عميل بيضيع عشان الرد اتأخر","اللي يبعتلك الساعة 2 الفجر بياخد رد وحجز في ساعتها، بدل ما يحجز عند غيرك."],["العميل ما بينساش ميعاده","بيوصله تذكير قبل الميعاد بيوم وبساعة. ولو عايز يغيّر الميعاد، بيغيّره من نفس المحادثة."],["فريقك يركّز مع العملاء اللي قدامه","الأسئلة المتكررة المساعد بيرد عليها، والسؤال الصعب بس هو اللي بيوصل لموظفك."],["كل الحجوزات في مكان واحد","كل حجز بيتسجل في تقويم جوجل، فتعرف يومك فيه إيه من أول نظرة."]],"qa":[["العميل هيعرف إنه بيكلم برنامج؟","المساعد بيرد بأسلوب طبيعي وبنفس لهجة العميل. ولو العميل سأله، بيقول إنه المساعد الذكي، والعميل يقدر يطلب موظف في أي وقت."],["ولو سأل عن حاجة المساعد مش عارفها؟","ما بيألّفش إجابة. بيحوّل المحادثة لموظف وبيوصلك تنبيه في ساعتها."],["لازم أجيب رقم جديد؟","محتاجين رقم موبايل مش شغّال على واتساب العادي، عشان نربطه بواتساب للأعمال الرسمي."],["التكلفة الشهرية بتتحسب إزاي؟","حوالي 150 – 300 ج.م لكل 1,000 رسالة، يعني على قد استخدامك."]]},"comment-reply":{"sub":"أي حد يسأل عن السعر على فيسبوك وإنستجرام، بيوصله الرد في الخاص في ساعتها","problem":"تعليقات «بكام؟» بتفضل بالساعات من غير رد، فالعميل بيزهق ويشتري من غيرك.","steps":["حد يكتب تعليق فيه «بكام» أو «السعر» أو «تفاصيل»","الصفحة ترد على تعليقه في ساعتها","يوصله في الخاص السعر والصور ولينك الطلب","الأسئلة اللي مش معتادة بتتحوّل ليك إنت"],"plain":["أي حد يكتب «بكام؟» تحت البوست بتاعك، بياخد رد على تعليقه في ثواني، وتوصله رسالة في الخاص فيها السعر والصور ولينك الطلب.","كل ده بيحصل لوحده، وإنت نايم أو مشغول. إنت اللي بتختار الكلمات اللي النظام يرد عليها، ونص الرد بيتكتب على مزاجك. والتعليق اللي فيه شكوى أو سؤال مش معتاد ما بيردش عليه لوحده، بيبعتهولك ترد بنفسك."],"story":"صفحة شنط جلد نزّلت بوست جديد، وسارة علّقت: «بكام دي وفيه ألوان إيه؟». بعد ثواني الصفحة ترد على تعليقها، وتوصلها رسالة في الخاص فيها السعر والألوان المتوفرة ولينك الطلب. سارة لسه متحمسة، فتطلب وهي في مكانها.","gains":[["العميل بيشتري وهو لسه متحمس","السعر بيوصله بعد ثواني من سؤاله، قبل ما يزهق ويروح لصفحة تانية."],["ما فيش تعليق بيتنسي","شغّال على البوستات العادية وعلى الإعلانات، مهما التعليقات كترت."],["المهم بس هو اللي بيوصلك","الأسئلة اللي مش معتادة والشكاوى ما بيردش عليها لوحده، بيحوّلها ليك ترد بنفسك."],["الصفحة بتتكلم بأسلوبك","إنت اللي بتختار الكلمات اللي يرد عليها ونص الرد اللي بيتبعت."]],"qa":[["بيرد على كل التعليقات؟","بيرد على الكلمات اللي إنت بتختارها، زي: بكام، السعر، تفاصيل. والنص اللي بيتبعت إنت اللي بتكتبه أو بنكتبه معاك."],["المطلوب مني إيه بعد التشغيل؟","تحدّث الأسعار والصور لما تتغير وبس. الباقي شغّال لوحده."],["شغّال على إنستجرام كمان؟","أيوه، على صفحة فيسبوك وحساب إنستجرام. بس لازم حساب إنستجرام يكون تجاري ومربوط بالصفحة."],["محتاجين مني إيه عشان نبدأ؟","صلاحية مشرف على الصفحة، والأسعار وصور المنتجات."]]},"site-assistant":{"sub":"عارف منتجاتك وأسعارك، بيرد على زوار موقعك، وبيجمعلك بيانات المهتمين","problem":"زوار موقعك عندهم أسئلة ومش لاقيين حد يرد عليهم، فبيقفلوا الصفحة ويمشوا.","steps":["بنجمع معلوماتك: الخدمات والأسعار والسياسات","المساعد بيتعلّم منها","يرد على الزوار ويقترح عليهم الأنسب ليهم","ياخد اسم ورقم المهتم ويبعتهملك"],"plain":["شبّاك محادثة صغير في موقعك، وراه مساعد عارف خدماتك وأسعارك. الزائر يسأل، والمساعد يرد عليه في ساعتها ويقترح عليه الحاجة الأنسب ليه.","ولما الزائر يبقى مهتم، المساعد ياخد اسمه ورقمه ويبعتهملك، فتكلمه وإنت عارف هو عايز إيه. وكمان بيطلعلك تقرير بأكتر الأسئلة اللي الناس بتسألها، فتعرف موقعك ناقصه إيه."],"story":"واحد دخل موقع شركة خدمات الساعة 1 بالليل وعايز يعرف السعر. بدل ما يدوّر في الصفحات ويقفل، يكتب سؤاله في شبّاك المحادثة وياخد الرد. المساعد ياخد اسمه ورقمه، والصبح الفريق يلاقي بياناته جاهزة ويكلمه.","gains":[["الزائر بيلاقي إجابة قبل ما يمشي","بدل ما يدوّر في الصفحات ويقفل الموقع، بيسأل وياخد الرد في ساعتها."],["بيانات المهتمين بتوصلك جاهزة","اسم ورقم وطلب كل زائر مهتم، فتتصل بيه وإنت عارف هو عايز إيه."],["بتعرف الناس بتسأل عن إيه","تقرير بأكتر الأسئلة تكرارًا، فتعرف موقعك وعروضك ناقصهم إيه."],["ما بيألّفش من دماغه","بيجاوب من ملفاتك إنت بس. والحاجة اللي مش موجودة فيها بيحوّلها لفريقك."]],"qa":[["بيعرف الإجابات منين؟","من ملفات الخدمات والأسعار اللي بتدّيهالنا. واللي مش لاقيه فيها ما بيألّفوش، بيحوّله لفريقك."],["بيشتغل على موقعي الحالي؟","أيوه. شبّاك المحادثة بيتركّب على أي موقع."],["أقدر أجرّبه قبل ما أطلبه؟","أيوه. المساعد اللي شغّال على موقعنا ده هو نفس الخدمة. جرّبه واسأله عن أي حاجة."],["محتاجين مني إيه؟","ملفات الخدمات والأسعار، وصلاحية نركّب الشبّاك على الموقع."]]},"cod-confirm":{"sub":"العميل بيأكد طلبه بضغطة قبل الشحن، والطلب الوهمي بيتلغي","problem":"من 25 لـ 30% من طلبات الدفع عند الاستلام بتترفض أو ما بتكملش، وإنت اللي بتدفع الشحن رايح جاي.","steps":["طلب جديد ييجي من المتجر أو من جدول الطلبات","رسالة واتساب تتبعت للعميل بتفاصيل الطلب","العميل يأكد أو يلغي بضغطة زرار","حالة الطلب تتحدّث لوحدها، واللي ما ردّش يوصله تذكير بعد كام ساعة"],"plain":["قبل ما تشحن أي طلب، النظام بيبعت للعميل رسالة واتساب فيها تفاصيل طلبه وزرارين: تأكيد أو إلغاء. الطلب اللي صاحبه ما أكدوش ما بيخرجش من المخزن.","كده إنت بتشحن للناس الجادة بس. مش محتاج موظف يتصل بكل عميل، وحالة كل طلب بتتحدّث لوحدها، وكل يوم بيوصلك تقرير بالطلبات."],"story":"متجر هدوم جاله طلب من أحمد: قميص قطن × 2 بـ 650 جنيه. قبل الشحن، أحمد وصلته رسالة واتساب بتفاصيل الطلب وزرارين. داس «تأكيد»، فالطلب اتشحن. لو كان داس «إلغاء» أو ما ردّش، الطلب كان فضل في المخزن والمتجر ما دفعش شحن على الفاضي.","gains":[["ما تدفعش شحن لطلب وهمي","الطلب اللي مش جاد بيتلغي قبل الشحن، فما تدفعش تمن المشوار رايح جاي."],["من غير مكالمات تأكيد","بدل ما موظف يتصل بكل عميل، العميل بيأكد بضغطة واحدة."],["عارف حالة كل طلب","حالة الطلب بتتحدّث لوحدها، واللي ما ردّش بيوصله تذكير، وإنت بيوصلك تقرير يومي."],["شغّال مع متجرك زي ما هو","بيتربط بـ Shopify وEasyOrders وWooCommerce، أو بجدول الطلبات لو بتسجّل فيه."]],"qa":[["ولو العميل ما ردّش؟","بيوصله تذكير بعد كام ساعة. والطلب بيفضل مش مؤكد لحد ما يرد، فما بيتشحنش."],["بيشتغل مع متجري؟","بيتربط بـ Shopify وEasyOrders وWooCommerce. ولو بتسجّل الطلبات في جدول، بيتربط بالجدول."],["التكلفة الشهرية كام؟","حوالي 200 – 400 ج.م لكل 1,000 طلب."],["محتاجين مني إيه؟","رقم واتساب للأعمال، وصلاحية على المتجر أو جدول الطلبات."]]},"cart-recovery":{"sub":"رسالة لكل واحد ساب السلة في متجرك، ومعاها لينك يكمّل منه الطلب","problem":"العملاء بيحطوا المنتجات في السلة وبعدين يمشوا، فبتضيع مبيعات كانت شبه مضمونة في آخر خطوة.","steps":["العميل يسيب السلة من غير ما يدفع","بعد ساعة توصله رسالة فيها المنتج ولينك يكمّل منه الطلب","لو ما رجعش، توصله رسالة تانية بعد يوم (ومعاها خصم صغير لو حبيت)","تقرير بالمبيعات اللي رجعت"],"plain":["السلة المتروكة يعني: عميل اختار منتج ووصل لصفحة الدفع، وبعدين خرج من غير ما يشتري. ده عميل كان على بُعد خطوة واحدة من الشراء.","النظام بيبعتله رسالة واتساب بعد ساعة تفكّره باللي اختاره، ومعاها لينك يكمّل منه على طول. ولو ما رجعش، رسالة تانية بعد يوم، وممكن تحط فيها خصم صغير لو عايز. وبيطلعلك تقرير بالمبيعات اللي رجعت بسبب الرسايل."],"story":"نورة حطّت عطر في السلة في متجر عطور، وانشغلت فقفلت الصفحة. بعد ساعة وصلتها رسالة واتساب تفكّرها بالعطر ومعاها لينك. دخلت منه وكمّلت الدفع. من غير الرسالة، كانت غالبًا هتنسى.","gains":[["مبيعات كانت هتضيع","ده عميل كان على بُعد خطوة من الشراء، ورسالة واحدة في وقتها ممكن ترجّعه."],["من غير أي مجهود منك","الرسايل بتطلع لوحدها في ميعادها، وبتقف لوحدها لما العميل يشتري."],["عارف رجّعت كام","تقرير بالمبيعات اللي رجعت بسبب الرسايل."],["الخصم في إيدك","كود الخصم اختياري، وإنت اللي بتحدد قيمته أو تلغيه خالص."]],"qa":[["الخصم إجباري؟","لأ. الخصم اختياري وفي الرسالة التانية بس، وإنت اللي بتحدد قيمته أو تلغيه."],["الرسايل هتضايق عملائي؟","رسالتين بس، وبيتبعتوا للي وافق يستقبل رسايل من متجرك."],["بيشتغل مع أنهي متاجر؟","سلة وزد وShopify."],["التكلفة الشهرية كام؟","على حسب عدد الرسايل اللي بتتبعت."]]},"lead-followup":{"sub":"رسايل متابعة للي سأل وما اشتراش، لحد ما ياخد قراره","problem":"عميل سأل عن السعر وبعدين سكت، ومحدش تابعه، فاشترى من غيرك.","steps":["كل عميل سأل بيتسجّل لوحده","بعد يوم: رسالة متابعة خفيفة","بعد 3 أيام: معلومة أو عرض يساعده ياخد القرار","اللي يرد بيتحوّل ليك ومعاه تنبيه"],"plain":["ناس كتير بتسأل عن السعر وبعدين تنشغل وتنسى. وساعات كل اللي محتاجينه حد يفكّرهم.","النظام بيسجّل كل واحد سأل، وبعد يوم يبعتله رسالة خفيفة، وبعد 3 أيام معلومة أو عرض يساعده يقرر. الرسالة بتتكتب على حسب هو سأل عن إيه، مش رسالة واحدة للكل. واللي يرد بيتحوّل ليك في ساعتها."],"story":"كريم سأل شركة عقارات عن شقة 3 غرف، قال السعر عالي وما ردّش تاني. بعد يوم وصلته رسالة خفيفة تطمّن عليه. وبعد 3 أيام وصلته معلومة عن التقسيط والمعاينة المجانية. كريم رد، والتنبيه وصل للمبيعات يكلموه.","gains":[["ما فيش عميل مهتم بيتنسي","كل واحد سأل بيتسجّل ويتابَع لوحده، حتى لو فريقك مشغول."],["رسالة تخص كل عميل","بتتكتب على حسب هو سأل عن إيه، مش رسالة واحدة منسوخة للكل."],["وقتك للي رد فعلًا","بيوصلك تنبيه لما العميل يرد، فتكلم الجاهزين بس."],["عارف المتابعة ماشية إزاي","بيوصلك تقرير كل أسبوع."]],"qa":[["كام رسالة بتوصل العميل؟","من رسالتين لتلاتة، وبعدها المتابعة بتقف. من غير زن ولا إلحاح."],["النظام بيوعد العميل بخصومات؟","لأ. بيستخدم نصوص العروض اللي إنت بتدّيهالنا وبس."],["العملاء بيتسجّلوا منين؟","من واتساب أو فورم أو الإعلانات، على حسب إنت بتستقبل عملاءك منين."],["مناسبة لأنهي شغل؟","للحاجة اللي سعرها عالي والعميل بياخد وقت يفكر فيها: عقارات، عربيات، كورسات."]]},"crm":{"sub":"كل عملاءك ومراحلهم في مكان واحد، مع تذكير للفريق وتقرير كل أسبوع","problem":"العملاء متوزعين بين واتساب والصفحة والورق، ومحدش عارف كل عميل وصل لفين.","steps":["كل رسالة من واتساب أو الصفحة بتتحوّل لعميل في النظام","كل عميل ليه مرحلة: مهتم، متابعة، اشترى","تذكير يومي للفريق بالمتابعات","تقرير أسبوعي بالمبيعات والعملاء جايين منين"],"plain":["CRM يعني دفتر عملاء ذكي. كل واحد كلّمك على واتساب أو الصفحة بيتسجّل فيه لوحده، ومعاه مرحلته: مهتم، متابعة، اشترى.","كل يوم الصبح النظام بيفكّر فريقك بالناس اللي لازم يكلموهم النهارده. وكل أسبوع بيوصلك تقرير بالمبيعات والعملاء جايين منين، فتعرف تحط فلوس الإعلانات فين."],"story":"معرض عربيات بيجيله عملاء من فيسبوك وواتساب والإعلانات. خالد سأل عن عربية موديل 2022، فاتسجّل لوحده كعميل «مهتم» والفريق وصله تنبيه. تاني يوم الساعة 9 الصبح، الفريق وصلته رسالة فيها أسماء اللي لازم يتابعوهم النهارده، وخالد منهم.","gains":[["كل عملاءك في مكان واحد","بدل ما يتوزعوا بين واتساب والصفحة والورق، بتشوفهم في لوحة واحدة."],["ما فيش متابعة بتتنسي","تذكير يومي للفريق بأسماء اللي لازم يتابعوهم."],["عارف عملاءك جايين منين","تقرير أسبوعي بالمبيعات ومصادر العملاء، فتعرف تحط ميزانية الإعلان فين."],["كل واحد شايف اللي يخصه","كل عضو في الفريق ليه صلاحياته."]],"qa":[["عندي جدول عملاء قديم، أعمل بيه إيه؟","بنبدأ منه. ادّينا الجدول الحالي لو موجود ونبني النظام عليه."],["كل الموظفين هيشوفوا كل حاجة؟","لأ. كل عضو في الفريق ليه صلاحياته، بيشوف اللي يخصه بس."],["بيتربط بإيه؟","بواتساب والصفحة والمخزون."],["مناسب لشغلي؟","معمول للشركات اللي عندها فريق مبيعات، والمعارض، والعيادات الكبيرة. لو شغلك لسه صغير، ممكن تبدأ بخدمة أبسط زي متابعة العملاء المهتمين."]]},"win-back":{"sub":"رسايل مخصوصة ترجّع اللي اشترى منك قبل كده يشتري تاني","problem":"عندك مئات العملاء اشتروا منك قبل كده، ومحدش بيكلمهم تاني.","steps":["بنقسّم العملاء على حسب آخر مرة اشتروا","رسالة باسم العميل وعرض يناسب اللي اشتراه","بتتبعت لوحدها كل أسبوع أو كل شهر","اللي يرد بكلمة «إيقاف» بيتشال من القايمة فورًا"],"plain":["عندك عملاء اشتروا منك مرة وما رجعوش. دول عارفينك وجرّبوا منتجك، وكل اللي ناقصهم سبب يرجعوا.","النظام بيبعت لكل واحد فيهم رسالة واتساب باسمه، فيها عرض يناسب اللي اشتراه قبل كده، كل أسبوع أو كل شهر. الرسايل بتتبعت للي وافق يستقبل عروض بس، واللي يكتب «إيقاف» بيتشال من القايمة في ساعتها."],"story":"منى اشترت جاكيت شتوي من متجر أزياء وما رجعتش من ساعتها. النهارده وصلتها رسالة باسمها عن خصم 15% على تشكيلة الشتا لحد يوم الحد. دي مش إعلان عام للكل، دي رسالة مكتوبة على حسب اللي هي اشترته.","gains":[["بتبيع للي عارفك","دول جرّبوا منتجك قبل كده، وكل اللي ناقصهم سبب يرجعوا."],["رسالة شخصية لكل عميل","باسمه وباللي اشتراه، مش إعلان عام للكل."],["رقمك في أمان","بتتبعت للي وافق على العروض بس، واللي يرد بكلمة «إيقاف» بيتشال من القايمة فورًا."],["عارف مين رجع","تقرير باللي رجعوا واشتروا."]],"qa":[["ممكن رقمي يتحظر؟","بنستخدم قوالب رسايل معتمدة من Meta، وبنبعت للي وافق بس. ده اللي بيحمي الرقم."],["تكلفة الرسايل كام؟","حوالي 3,500 ج.م لكل 1,000 رسالة عرض في مصر، بتتدفع لواتساب وباسمك."],["الرسايل بتتبعت كل قد إيه؟","كل أسبوع أو كل شهر، على حسب ما تختار."],["محتاجين مني إيه؟","قايمة العملاء السابقين وموافقتهم على العروض، والعروض اللي عايز تقدمها."]]},"product-photos":{"sub":"من صورة بالموبايل لصور احترافية بخلفيات ومشاهد مختلفة","problem":"التصوير الاحترافي غالي وبياخد وقت، وصور الموبايل ما بتقنعش العميل يشتري.","steps":["تبعتلنا صور واضحة للمنتج بالموبايل","بنحط المنتج في مشاهد احترافية بألوان البراند بتاعك","بنسلّمك من 20 لـ 50 صورة بمقاسات المنصات والمتجر","جولة تعديل مجانية"],"plain":["تبعتلنا صور منتجك بالموبايل، ونرجّعهالك صور احترافية: نفس المنتج، بس في مشاهد وخلفيات مختلفة بألوان البراند بتاعك، كأنها طالعة من استوديو تصوير.","مش محتاج تحجز استوديو ولا تجيب مصوّر ولا تنقل المنتجات. بتستلم من 20 لـ 50 صورة بمقاسات البوست والستوري والمتجر في خلال 2 لـ 4 أيام، ومعاهم جولة تعديل مجانية لو فيه حاجة عايز تغيّرها."],"story":"براند عطور عنده إزازة عطر جديدة، وصاحبه صوّرها بالموبايل على الترابيزة. بعد كام يوم بيستلم صور لنفس الإزازة في مشاهد فخمة بالأسود والدهبي، جاهزة للبوستات والستوري وصفحة المنتج في المتجر.","gains":[["من غير استوديو ولا مصوّر","لا حجز ولا نقل منتجات ولا يوم تصوير. صور الموبايل كفاية."],["صور تكفّي كل مكان","من 20 لـ 50 صورة بمقاسات البوست والستوري والمتجر."],["جاهزة في أيام","التسليم في خلال 2 لـ 4 أيام، ومعاه جولة تعديل مجانية."],["بألوان البراند بتاعك","الخلفيات بتتعمل على ألوان وأسلوب علامتك."]],"qa":[["شكل منتجي هيتغير في الصور؟","اللي بيتغير الخلفية والمشهد والإضاءة، والمنتج بيفضل منتجك. ولو طلعت صورة مش شبهه بنعدّلها في جولة التعديل."],["أبعت صور عاملة إزاي؟","صور واضحة للمنتج من أكتر من زاوية، ومعاها ألوان وأسلوب البراند."],["فيه تكلفة شهرية؟","لأ، ما فيش."],["مناسبة لأنهي منتجات؟","هدوم، مجوهرات، مستحضرات تجميل، وأكل."]]},"ad-video":{"sub":"فيديو قصير جاهز للإعلان، بمتحدث افتراضي أو مشاهد معمولة بالذكاء الاصطناعي","problem":"الفيديو بيبيع أكتر من الصورة، بس التصوير والمونتاج غاليين.","steps":["بنكتب نص مدته من 15 لـ 30 ثانية","بنعمل المشاهد أو متحدث افتراضي","مونتاج مع كتابة على الشاشة وموسيقى","التسليم بمقاس الريلز والستوري"],"plain":["فيديو قصير من 15 لـ 30 ثانية جاهز تنزّله إعلان. إحنا بنكتب النص، وبنعمل المشاهد أو متحدث افتراضي بالذكاء الاصطناعي، وبنضيف الكتابة على الشاشة والموسيقى.","مش محتاج كاميرا ولا مكان تصوير ولا ممثلين ولا مونتير. بتدّينا المنتج والعرض واللوجو والألوان، وبتستلم الفيديو في خلال 2 لـ 3 أيام بنسختين بمقاسين مختلفين."],"story":"متجر عنده عرض «خصم 10% لأول 100 طلب» وعايز يلحق ينزّله إعلان الأسبوع ده. بدل ما يدوّر على مصوّر ومونتير، بيبعت المنتج والعرض، وبعد يومين تلاتة بيستلم فيديو جاهز للريلز والستوري.","gains":[["من غير تصوير ولا ممثلين","لا كاميرا ولا مكان تصوير ولا مونتاج من ناحيتك."],["جاهز لكل المنصات","نسختين بمقاسين مختلفين، للريلز وللستوري."],["سريع كفاية يلحق عرض الأسبوع","التسليم في خلال 2 لـ 3 أيام، فتلحق بيه عرضك أو نزول منتجك الجديد."],["النص علينا","بنكتب نص الإعلان من معلومات منتجك وعرضك."]],"qa":[["يعني إيه متحدث افتراضي؟","شخصية معمولة بالذكاء الاصطناعي بتتكلم عن منتجك قدام الكاميرا، بدل ما تصوّر شخص حقيقي."],["أنا اللي هكتب نص الإعلان؟","لأ. إحنا بنكتبه من معلومات منتجك وعرضك."],["الفيديو مدته قد إيه؟","من 15 لـ 30 ثانية، ومعمول لإعلانات فيسبوك وتيك توك وسناب."],["فيه تكلفة شهرية؟","لأ، ما فيش."]]},"content-autopilot":{"sub":"بوستات بتتكتب وتتصمم وتتنشر في ميعادها، وإنت بس بتوافق","problem":"ما عندكش وقت تكتب وتصمم كل يوم، فالصفحة بتقف والعملاء بينسوك.","steps":["خطة شهرية بالأفكار","البوستات بتتكتب وتتصمم","بتوصلك على واتساب توافق أو تعدّل","بتتنشر لوحدها في ميعادها"],"plain":["صفحتك بتنشر بانتظام من غير ما تكتب ولا تصمم. إحنا بنجهّز خطة الشهر، ونكتب البوستات ونصممها.","كل بوست بيوصلك على واتساب الأول: تقول «موافق» أو تطلب تعديل. بعد كده بيتنشر لوحده في ميعاده. يعني ما فيش حاجة بتنزل على صفحتك من غير ما تشوفها."],"story":"صالون تجميل صاحبته مشغولة مع الزباين طول اليوم، والصفحة واقفة. مع الخدمة، بتوصلها بوستات الأسبوع على واتساب، تبص عليها في دقيقة وتدوس «موافق»، والصفحة تفضل شغّالة طول الشهر.","gains":[["صفحة شغّالة طول الشهر","من 12 لـ 20 بوست بتصميماتهم، فالصفحة ما تقفش والعملاء ما ينسوكش."],["دقيقة واحدة منك","كل المطلوب إنك تدوس «موافق» على واتساب."],["ما فيش حاجة بتنزل من غير علمك","كل بوست بيعدّي عليك الأول، وتعدّل اللي إنت عايزه قبل النشر."],["الأفكار علينا","بنعمل خطة الشهر من معلومات شغلك وعروضك."]],"qa":[["ليه السعر فيه جزء شهري؟","الجزء الأول تجهيز وبيتدفع مرة واحدة. والجزء الشهري قصاد محتوى كل شهر: الخطة والكتابة والتصميم والنشر."],["محتاج أبعتلكم أفكار؟","لأ. محتاجين معلومات شغلك وعروضك، والأفكار علينا."],["ولو بوست مش عاجبني؟","بتكتب التعديل اللي عايزه على واتساب، والبوست بيتعدّل قبل ما يتنشر."],["محتاجين مني إيه؟","معلومات الشغل والعروض، وصلاحية على الصفحات."]]},"google-reviews":{"sub":"بيطلب التقييم من العملاء المبسوطين، وبيرد على كل تقييم","problem":"العميل المبسوط قليل لما يكتب تقييم، والزعلان دايمًا بيكتب. والتقييمات هي اللي بتخلّي الناس تختارك.","steps":["بعد الخدمة: رسالة تطلب من العميل يقيّمك","كل تقييم جديد بياخد رد مناسب","التقييم الوحش بيوصلك عنه تنبيه فورًا","تقرير شهري بالتقييمات"],"plain":["تقييمات جوجل هي النجوم اللي الناس بتشوفها جنب اسم شغلك في الخرايط والبحث.","النظام بيبعت لكل عميل بعد الخدمة رسالة تطلب منه يقيّمك، وبيرد على كل تقييم جديد. ولو جه تقييم وحش، بيوصلك تنبيه في ساعتها عشان تتصرف قبل ما المشكلة تكبر."],"story":"عيادة أسنان، وهالة كتبت تقييم نجمتين: «استنيت ساعة كاملة بعد ميعادي». التقييم بياخد رد مهذب، وصاحب العيادة بيوصله تنبيه في ساعتها، فيكلمها ويحل المشكلة.","gains":[["تقييمات أكتر من عملاء مبسوطين","العميل المبسوط غالبًا ما بيقيّمش من نفسه. رسالة بسيطة بعد الخدمة بتفكّره."],["كل تقييم بياخد رد","الرد على التقييمات بيبيّن إن ورا الشغل ده حد مهتم."],["بتعرف المشكلة في ساعتها","التقييم الوحش بيوصلك عنه تنبيه فورًا، فتكلم العميل قبل ما المشكلة تكبر."],["عارف ماشي إزاي","تقرير شهري بالتقييمات."]],"qa":[["بتكتبوا تقييمات مش حقيقية؟","لأ. النظام بيطلب التقييم من عملاءك الحقيقيين بس، بعد ما ياخدوا الخدمة."],["إيه اللي بيحصل لما ييجي تقييم وحش؟","بيتكتب عليه رد مهذب، وبيوصلك تنبيه فورًا عشان تتصرف."],["التكلفة الشهرية كام؟","حوالي 20 – 100 ج.م."],["محتاجين مني إيه؟","صلاحية على ملف شغلك في جوجل، وأرقام العملاء بعد الخدمة."]]},"invoice-ai":{"sub":"صورة الفاتورة أو ملف PDF بيتحوّل لسطر مترتب في ثواني","problem":"موظف بيقعد بالساعات ينقل الفواتير بإيده، وساعات بيغلط.","steps":["تصوّر الفاتورة أو تبعت ملف PDF على واتساب أو الإيميل","النظام يقرا المورّد والتاريخ والمبلغ والبنود","يضيفها سطر في الجدول أو برنامج المحاسبة","أي فاتورة مش واضحة بتتعلّم للمراجعة"],"plain":["بدل ما الموظف ينقل كل فاتورة بإيده، بيصوّرها أو يبعت ملف PDF على واتساب أو الإيميل. النظام بيقرا اسم المورّد والتاريخ والمبلغ والبنود، ويضيفهم سطر مترتب في الجدول أو برنامج المحاسبة.","ولو الفاتورة مش واضحة، النظام ما بيخمّنش الأرقام. بيعلّم عليها للمراجعة عشان حد يبص عليها بنفسه. وكل شهر بيطلعلك تقرير بالمصروفات."],"story":"مكتب محاسبة بتوصله فواتير موردين كل يوم. المحاسب بيصوّر الفاتورة بالموبايل ويبعتها، وفي ثواني تتسجّل: المورّد، المبلغ، وعدد البنود. والفاتورة اللي صورتها مش واضحة بتتعلّم للمراجعة، وما بتتسجّلش بأرقام غلط.","gains":[["ساعات النقل بقت ثواني","الفاتورة بتتسجّل أول ما صورتها تتبعت."],["غلطات أقل","لا رقم بيتكتب غلط ولا فاتورة بتتنسي في الدرج."],["الفاتورة اللي مش واضحة ما بتعدّيش","بتتعلّم للمراجعة بدل ما تتسجّل بأرقام غلط."],["عارف مصروفاتك","تقرير شهري بالمصروفات."]],"qa":[["بيقرا الفواتير العربي؟","أيوه، بيقرا الصور وملفات PDF بالعربي والإنجليزي."],["البيانات بتروح فين؟","للجدول أو برنامج المحاسبة اللي إنت شغّال عليه، وبالأعمدة اللي إنت بتحددها."],["ولو الصورة مش واضحة؟","ما بتتسجّلش. بتتعلّم للمراجعة عشان حد يراجعها."],["محتاجين مني إيه؟","نماذج من فواتيرك، والأعمدة اللي محتاجها في الجدول."]]},"landing-page":{"sub":"سريع، مظبوط على الموبايل، ومربوط بواتساب وبيكسل الإعلانات","problem":"إعلانك بيودّي العميل لصفحة بطيئة، أو ما فيش صفحة أصلًا، فبيمشي.","steps":["بنفهم عرضك والعميل اللي عايز توصله","بنكتب المحتوى بالعربي ونصمم الصفحة","بنربطها بواتساب وبيكسل الإعلانات","بنطلّعها على دومين باسمك"],"plain":["صفحة الهبوط هي صفحة واحدة بيوصلها اللي يدوس على إعلانك. فيها عرضك وصور شغلك وأسعارك، وزرار يفتح واتساب برسالة جاهزة. والموقع الكامل نفس الفكرة بس بصفحات أكتر.","إحنا بنكتب المحتوى ونصمم الصفحة، ونربطها ببيكسل الإعلانات، وده أداة قياس بتعرّفك مين داس ومين طلب. والدومين والاستضافة بيبقوا باسمك إنت، مش باسمنا."],"story":"شركة خدمات بتصرف على إعلانات، واللي بيدوس على الإعلان مش لاقي صفحة تشرحله العرض. مع صفحة الهبوط، بيوصل لصفحة سريعة على الموبايل فيها العرض والسعر، ويدوس زرار واتساب يبعت رسالة جاهزة.","gains":[["إعلانك ما بيضيعش","اللي يدوس على الإعلان بيوصل لصفحة سريعة ومريحة على الموبايل، فما يمشيش."],["عارف نتيجة إعلانك","بنربطها ببيكسل الإعلانات، وده أداة قياس بتعرف بيها مين داس ومين طلب."],["كل حاجة باسمك","الدومين والاستضافة باسمك، مش باسمنا."],["المحتوى علينا","بنكتب الكلام بالعربي ونصمم الصفحة، وإنت بتدّينا اللوجو والصور والعرض."]],"qa":[["إيه الفرق بين الصفحة والموقع؟","الصفحة لعرض واحد أو إعلان واحد. الموقع بيعرّف بشغلك كله في كذا صفحة."],["أنا اللي هكتب المحتوى؟","لأ. بنكتب المحتوى بالعربي ونصمم الصفحة، وإنت بتدّينا اللوجو والصور والعرض."],["بتاخد وقت قد إيه؟","الصفحة من 3 لـ 7 أيام، والموقع من أسبوعين لتلاتة."],["فيه تكلفة بعد التسليم؟","حوالي 100 ج.م استضافة، ودومين بيتجدد كل سنة."]]},"company-site":{"sub":"موقع احترافي بيعرض خدماتك، وفيه مساعد بيرد على الزوار ويجمعلك المهتمين","problem":"موقعك قديم أو مش موجود، والزائر مش لاقي إجابة سريعة، فبيمشي قبل ما يكلمك.","steps":["بنحدد الصفحات والرسالة الأساسية لشركتك","بنصمم الموقع ونكتب المحتوى بالعربي والإنجليزي","بنضيف المساعد الذكي ونربطه بواتساب والإيميل","بنطلّعه على الدومين بتاعك ونظبّط ظهوره في جوجل"],"plain":["موقع رسمي لشركتك بيعرض خدماتك وشغلك اللي فات، بالعربي والإنجليزي، وبتصميم معمول على هوية شركتك.","وجوّاه مساعد ذكي متدرّب على خدماتك: بيرد على الزائر، وياخد اسمه ورقمه ويبعتهملك على واتساب والإيميل، بدل ما الزائر يتفرج ويمشي. وبنظبّط الموقع عشان يظهر للي بيدوّر على خدماتك في جوجل."],"story":"مكتب هندسي، وعميل بيدوّر عليه في جوجل قبل ما يكلمه. بيلاقي موقع مترتب فيه الخدمات والمشاريع السابقة، يسأل المساعد سؤال وياخد الرد، ويسيب رقمه. المكتب بيتصل بيه وهو عارف هو محتاج إيه.","gains":[["شكل محترم قدام العميل","تصميم مخصوص بهوية شركتك، بيدّي ثقة قبل أول مكالمة."],["الزائر بيتحوّل لعميل مهتم","المساعد بيرد ويجمع الاسم والرقم ويبعتهملك على واتساب والإيميل."],["اللي بيدوّر في جوجل يلاقيك","تظبيط أساسي لمحركات البحث عشان موقعك يظهر للي بيدوّر على خدماتك."],["عارف مين بيزور موقعك","بنربط الموقع بتحليلات الزيارات."]],"qa":[["بيشمل كام صفحة؟","لحد 8 صفحات بلغتين: عربي وإنجليزي."],["الدومين باسمي؟","أيوه. بنطلّعه على الدومين بتاعك أو على اسم تختاره، وباسمك."],["مين بيكتب المحتوى؟","إحنا بنكتبه بالعربي والإنجليزي، من معلومات خدماتك وشغلك السابق."],["فيه تكلفة شهرية؟","حوالي 150 – 600 ج.م للاستضافة وتشغيل المساعد."]]},"smart-store":{"sub":"متجر بياخد الطلب، يبعت الفاتورة، يأكد الشحن، ويقترح منتجات لكل عميل","problem":"بتبيع بالرسايل وبإيدك: تسجيل الطلب والفاتورة والشحن والمتابعة، وكل ده بياخد وقت فريقك.","steps":["بنختار المنصة المناسبة: Shopify أو سلة أو زد أو متجر خاص","بنرفع المنتجات ونصمم المتجر","بنربط الدفع والشحن ورسايل واتساب التلقائية","بنضيف ترشيحات المنتجات واسترجاع السلات"],"plain":["متجر إلكتروني شغّال لوحده. العميل يطلب ويدفع، فتوصله الفاتورة ورسالة الشحن على واتساب من غير ما حد من فريقك يكتب حاجة.","وبعد كده المتجر بيقترح على كل عميل منتجات تناسب اللي اشتراه، وبيبعت رسالة للي ساب السلة. إحنا بنختار معاك المنصة، ونرفع لحد 100 منتج، ونربط الدفع والشحن."],"story":"براند بيبيع من الرسايل: حد يرد، حد يسجّل الطلب، حد يكتب الفاتورة، وحد يتابع الشحن. مع المتجر، العميل بيطلب ويدفع لوحده، والفاتورة ورسالة الشحن بيوصلوه، والفريق بيركّز في تجهيز الطلبات.","gains":[["بيع من غير رسايل بالإيد","لا تسجيل طلبات ولا كتابة فواتير ولا متابعة شحن من فريقك."],["كل طلب متوثّق","فاتورة ورسالة شحن لكل طلب، بيوصلوا العميل لوحدهم."],["مبيعات زيادة","ترشيحات منتجات لكل عميل، واسترجاع للي ساب السلة."],["المنصة اللي تناسبك","بنختار معاك: Shopify أو سلة أو زد أو متجر خاص."]],"qa":[["المتجر بيتبني على أنهي منصة؟","بنختار معاك الأنسب: Shopify أو سلة أو زد أو متجر خاص."],["بترفعوا كام منتج؟","لحد 100 منتج جوّه الخدمة، مع ربط الدفع والشحن."],["التكلفة الشهرية إيه؟","اشتراك المنصة، وفوقه حوالي 300 – 1,000 ج.م تشغيل."],["محتاجين مني إيه؟","صور المنتجات وأسعارها، وحساب بوابة الدفع وشركة الشحن، وسياسة الاستبدال والاسترجاع."]]},"dashboard":{"sub":"نظام ويب تدير منه شغلك اليومي، ومعاه تقارير وملخصات ذكية بتطلع لوحدها","problem":"الشغل ماشي على جداول متفرقة وواتساب، وما فيش صورة واضحة للي بيحصل كل يوم.","steps":["بنقعد مع فريقك ونرسم الشغل ماشي إزاي دلوقتي","بنصمم الشاشات والصلاحيات","بنبني النظام ونربطه بالبيانات الحالية","بنضيف تقارير وملخصات الذكاء الاصطناعي بيكتبها لوحده"],"plain":["نظام بيفتح من المتصفح وبيجمع شغلك اليومي في شاشة واحدة، بدل الجداول المتفرقة ورسايل واتساب.","كل يوم الصبح الذكاء الاصطناعي بيكتبلك ملخص باللي حصل، وتقدر تسأله فيجاوبك من بياناتك. كل موظف بيشوف الشاشات اللي تخص شغله بس، وإحنا بندرّب الفريق عليه."],"story":"شركة توزيع عندها كذا فرع، وكل فرع بيبعت أرقامه في جدول لوحده على واتساب، والمدير بيقعد يجمّعهم. مع النظام، بيفتح شاشة واحدة يلاقي اللي اتباع واللي قرّب يخلص وأنهي فرع ماشي أحسن، من غير ما يطلب تقرير من حد.","gains":[["صورة واضحة كل يوم","بتعرف إيه اللي اتباع وإيه اللي قرّب يخلص وأنهي فرع ماشي أحسن، من غير ما تطلب تقرير من حد."],["كل موظف شايف اللي يخصه","صلاحيات مختلفة لكل دور في الشركة."],["مش هتبدأ من الصفر","بنربط النظام بجداولك وأنظمتك الحالية."],["الفريق بيتدرّب عليه","تدريب الفريق جزء من الخدمة."]],"qa":[["بتدرّبوا الفريق عليه؟","أيوه، تدريب الفريق جزء من الخدمة."],["بتعرفوا إحنا محتاجين إيه إزاي؟","بنقعد مع فريقك ونرسم طريقة الشغل الحالية الأول، وبعدين نصمم الشاشات عليها."],["بياخد وقت قد إيه؟","من 4 لـ 8 أسابيع."],["فيه تكلفة شهرية؟","حوالي 500 – 2,500 ج.م استضافة وصيانة."]]},"booking-app":{"sub":"تطبيق لعملاءك يحجزوا منه ويدفعوا، ومعاه مساعد بيرد على أسئلتهم","problem":"الحجز بالتليفون والرسايل متعب، والعملاء عايزين تطبيق يشوفوا فيه المواعيد ويحجزوا منه على طول.","steps":["بنحدد الشاشات: الخدمات، المواعيد، الحجز، الدفع، الحساب","بنصمم واجهة بهويتك ونراجعها معاك","بنبني التطبيق لـ Android وiOS ولوحة إدارة ليك","بننشره على المتاجر ونتابع معاك أول شهر"],"plain":["تطبيق باسم شغلك على Android وiPhone. عميلك يفتحه، يشوف الخدمات والمواعيد الفاضية، يحجز ويدفع، ويوصله تذكير قبل الميعاد.","وجوّاه مساعد ذكي بيرد على أسئلة العميل. وإنت عندك لوحة إدارة بتشوف منها كل الحجوزات. وإحنا اللي بننشر التطبيق على Google Play وApp Store، على حسابات باسمك إنت."],"story":"جيم، والأعضاء بيتصلوا يسألوا على مواعيد الكلاسات، والاستقبال مش ملاحق. مع التطبيق، العضو يفتح الموبايل، يشوف المواعيد الفاضية، يحجز ويدفع، ويوصله تذكير. والاستقبال يفضى للي واقف قدامه.","gains":[["حجز من غير مكالمات","العميل بيحجز لوحده في أي وقت، وفريقك مش قاعد على التليفون طول اليوم."],["اسمك على موبايل عميلك","تطبيقك موجود عنده على طول، فيرجعلك بدل ما يدوّر على غيرك."],["كل الحجوزات قدامك","لوحة إدارة للحجوزات، مع إشعارات وتذكيرات بتطلع لوحدها."],["الدفع من التطبيق","العميل بيدفع إلكتروني وهو بيحجز."]],"qa":[["مين بينشر التطبيق على المتاجر؟","إحنا بننشره، على حسابات المطوّر في Google Play وApp Store باسمك إنت."],["العميل بيدفع من التطبيق؟","أيوه، فيه دفع إلكتروني."],["بياخد وقت قد إيه؟","من 6 لـ 10 أسابيع، وبنتابع معاك أول شهر بعد النشر."],["فيه تكلفة شهرية؟","حوالي 800 – 2,500 ج.م سيرفرات وصيانة."]]},"ordering-app":{"sub":"تطبيق طلبات لمطعمك أو متجرك، بيقترح على كل عميل اللي يناسبه","problem":"بتدفع عمولة كبيرة لتطبيقات التوصيل، وما عندكش بيانات عملاءك ولا طريقة تكلمهم.","steps":["بنحدد المنيو أو الكتالوج ومناطق التوصيل","بنصمم تجربة طلب سريعة","بنبني التطبيق ولوحة الطلبات للمطبخ أو المخزن","بنضيف الترشيحات الذكية والعروض المخصوصة"],"plain":["تطبيق طلبات بتاع مطعمك أو متجرك إنت، بدل ما تعتمد على تطبيقات التوصيل. العميل بيطلب منه مباشرة، والتطبيق بيفتكر طلبه المعتاد ويقترح عليه اللي يناسبه.","الطلب بيوصل على لوحة في المطبخ أو المخزن، والدفع إلكتروني أو كاش. وبيانات عملاءك بتبقى عندك: عارف مين بيطلب وبيطلب إيه، وتبعتله عروضك ونقط الولاء."],"story":"مطعم كل طلباته جاية من تطبيقات التوصيل، بيدفع عمولة على كل طلب، ومش عارف يكلم زباينه. مع تطبيقه، الزبون اللي بيطلب دايمًا يلاقي زرار «اطلب تاني» وعرض معمول ليه، والطلب يوصل المطبخ مباشرة.","gains":[["الطلب بيوصلك مباشرة","العميل بيطلب من تطبيقك إنت، مش من تطبيق بياخد عمولة على كل طلب."],["بيانات عملاءك عندك","عارف مين بيطلب وبيطلب إيه، وتكلمه بعروضك."],["عملاء بيرجعوا","نقط ولاء وعروض مخصوصة وزرار «اطلب تاني»."],["المطبخ شايف كل طلب","لوحة طلبات للمطبخ أو المخزن، ومعاها إدارة المنيو."]],"qa":[["بيقبل الدفع كاش؟","أيوه، فيه دفع إلكتروني وكاش."],["الطلبات بتوصل المطبخ إزاي؟","على لوحة طلبات للمطبخ أو المخزن، ومعاها إدارة المنيو."],["بياخد وقت قد إيه؟","من 8 لـ 12 أسبوع."],["محتاجين مني إيه؟","المنيو أو الكتالوج بالأسعار والصور، ومناطق التوصيل وتكلفتها، وحسابات المطوّر على المتاجر."]]},"team-app":{"sub":"تطبيق لفريقك: مهام، حضور، طلبات، ومساعد بيجاوب من ملفات الشركة","problem":"الفريق بيتكلم في جروبات واتساب متفرقة، والمهام والطلبات بتضيع، والموظف الجديد بيسأل نفس الأسئلة.","steps":["بنحدد الفريق محتاج إيه كل يوم: مهام، حضور، طلبات، تقارير","بنصمم الشاشات لكل دور","بنبني التطبيق ولوحة الإدارة","بنضيف مساعد بيجاوب من سياسات وملفات الشركة"],"plain":["تطبيق لموظفينك بدل جروبات واتساب المتفرقة. فيه المهام، والحضور، والطلبات زي الإجازات، وكل حاجة ليها مكان وصاحب وحالة.","وجوّاه مساعد بيجاوب الموظف من سياسات وملفات الشركة، فالموظف الجديد ما يفضلش يسأل زمايله نفس الأسئلة. والمدير بيوصله تنبيه بالطلبات الجديدة وتقرير كل أسبوع."],"story":"محمود عايز يعرف سياسة الإجازات المرضية. بدل ما يسأل في الجروب، بيسأل المساعد في التطبيق وياخد الإجابة من ملفات الشركة، ويقدّم طلب الإجازة من نفس التطبيق. والمدير بيوصله تنبيه بالطلب.","gains":[["ما فيش مهمة بتضيع","كل مهمة وكل طلب ليه مكان وصاحب وحالة."],["الموظف الجديد بيلاقي الإجابة","بيسأل المساعد عن أي سياسة، بدل ما يكرر نفس الأسئلة على زمايله."],["المدير شايف الصورة","تنبيهات بالطلبات الجديدة وتقارير أسبوعية."],["شاشات على قد كل دور","كل موظف بيشوف اللي يخص شغله، والإدارة ليها لوحة خاصة."]],"qa":[["بيتربط بالأنظمة اللي عندنا؟","أيوه، بنربطه بالأنظمة اللي شغّالين عليها."],["كل الموظفين هيشوفوا نفس الشاشات؟","لأ. الشاشات بتتصمم لكل دور، والإدارة ليها لوحة خاصة."],["المساعد بيجاوب منين؟","من سياسات وملفات الشركة اللي بتدّوهالنا."],["بياخد وقت قد إيه؟","من 6 لـ 10 أسابيع."]]},"app-mvp":{"sub":"بنحوّل فكرة تطبيقك المعتمد على الذكاء الاصطناعي لنسخة أولى جاهزة للتجربة والعرض على المستثمرين","problem":"عندك فكرة تطبيق، بس مش عارف تبدأ منين، وإنك تبني كل حاجة مرة واحدة غالي ومخاطرة.","steps":["قعدة نحدد فيها أهم ميزة لازم تشتغل في النسخة الأولى","نماذج شاشات تفاعلية تجرّب بيها الفكرة قبل البرمجة","نبني النسخة الأولى بالمميزات الأساسية بس","إطلاق تجريبي مع مستخدمين حقيقيين وقياس النتايج"],"plain":["MVP يعني نسخة أولى صغيرة من تطبيقك، فيها أهم ميزة بس. بتتبني بسرعة وبتكلفة أقل من التطبيق الكامل.","الفكرة إنك تجرّبها مع مستخدمين حقيقيين وتعرضها على المستثمرين قبل ما تصرف على الباقي. بنبدأ بقعدة نحدد فيها أهم ميزة، وبعدين نماذج شاشات تجرّب بيها الفكرة قبل ما نبدأ برمجة. والكود في الآخر بيبقى باسمك."],"story":"واحد عنده فكرة تطبيق وخايف يصرف عليها وبعدين يطلع الناس مش عايزاه. بيبدأ بنسخة فيها الميزة الأساسية بس: أول أسبوعين نماذج شاشات، وبعدين بناء الميزة، وبعدين إطلاق تجريبي لـ 50 مستخدم وتقرير بالنتايج. ساعتها بيقرر الخطوة الجاية وهو شايف نتايج حقيقية.","gains":[["بتختبر الفكرة قبل المخاطرة","بتعرف الناس عايزة تطبيقك فعلًا ولا لأ، قبل ما تبني كل حاجة."],["حاجة حقيقية تعرضها","تطبيق شغّال قدام المستثمر أقوى من عرض على ورق."],["الكود ملكك","الكود المصدري باسمك، وتكمّل عليه مع أي فريق."],["بتشوف الشكل قبل البرمجة","نماذج شاشات تفاعلية تجرّب بيها الفكرة قبل ما نبدأ نبني."]],"qa":[["فكرتي لسه مش واضحة، أبدأ؟","بنبدأ بقعدة نحدد فيها أهم ميزة لازم تشتغل في النسخة الأولى، وبعدين نماذج شاشات تجرّب بيها الفكرة قبل البرمجة."],["وبعد النسخة الأولى؟","إطلاق تجريبي مع مستخدمين حقيقيين وقياس النتايج، وعليها بتقرر الخطوة اللي بعدها."],["بياخد وقت قد إيه؟","من 6 لـ 12 أسبوع."],["محتاجين مني إيه؟","وصف الفكرة والعميل اللي بتستهدفه، وأمثلة لتطبيقات شبهها، وميزانية وميعاد مستهدف."]]}};
S.forEach(s => { const m = MORE[s.id]; ['sub','problem','steps'].forEach(k => { if (m && m[k]) s[k] = m[k]; }); });
